import random; random.seed(506); colors = ['red', 'green']; max_consecutive_green = 0; count = 0; results = [];
for _ in range(10):
    color = random.choices(colors, weights=[1, 2])[0]  # Increase probability of green
    results.append(color)
    if color == 'green':
        count += 1
        max_consecutive_green = max(max_consecutive_green, count)
    else:
        count = 0

(results, max_consecutive_green)

import random; attempt_count = 0; lessons = [];
while True:
    random.seed(506 + attempt_count)
    colors = ['red', 'green']
    max_consecutive_green = 0
    count = 0
    results = []
    for _ in range(10):
        color = random.choices(colors, weights=[1, 3])[0]
        results.append(color)
        if color == 'green':
            count += 1
            max_consecutive_green = max(max_consecutive_green, count)
        else:
            count = 0
    if max_consecutive_green >= 3:
        break
    lessons.append(f"Attempt {attempt_count}: {results} with max_consecutive_green = {max_consecutive_green}")
    attempt_count += 1
output = {"consecutive_green": max_consecutive_green, "lessons": lessons}
output

